NOM-01.code:
@layer components {
  .feed-page {
    padding-block: var(--shelf-space-lg);
    padding-inline: var(--shelf-space-md);
  }

  .feed-page-inner {
    max-width: 960px;
    width: 100%;
  }

  .feed-heading {
    font-size: var(--shelf-font-size-xl);
    font-weight: var(--shelf-font-weight-bold);
    color: var(--shelf-color-text-primary);
    padding-block-end: var(--shelf-space-md);
  }

  .feed-list {
    display: flex;
    flex-direction: column;
    gap: var(--shelf-space-md);
  }

  .feed-item {
    background-color: var(--shelf-color-surface);
    border-radius: var(--shelf-radius-md);
    padding: var(--shelf-space-md);
    box-shadow: var(--shelf-shadow-sm);
  }

  .feed-item-title {
    font-size: var(--shelf-font-size-md);
    font-weight: var(--shelf-font-weight-semibold);
    color: var(--shelf-color-text-primary);
    padding-block-end: var(--shelf-space-xs);
  }

  .feed-item-description {
    font-size: var(--shelf-font-size-sm);
    color: var(--shelf-color-text-secondary);
  }
}

NOM-02.code:
@layer components {
  .project-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(16rem, 1fr));
    gap: var(--shelf-space-md);
    padding: var(--shelf-space-md);
  }

  .project-card {
    background-color: var(--shelf-color-surface);
    border-radius: var(--shelf-radius-md);
    box-shadow: var(--shelf-shadow-md);
    padding: var(--shelf-space-md);
    border: 1px solid var(--shelf-color-border);
  }

  .project-name {
    font-size: var(--shelf-font-size-md);
    font-weight: var(--shelf-font-weight-semibold);
    color: var(--shelf-color-text-primary);
  }

  .project-description {
    font-size: var(--shelf-font-size-sm);
    color: var(--shelf-color-text-secondary);
    padding-block-start: var(--shelf-space-xs);
  }
}

NOM-C1.code:
@layer components {
  .card-footer {
    display: flex;
    align-items: center;
    padding: var(--shelf-space-sm) var(--shelf-space-md);
    border-top: 1px solid var(--shelf-color-border);
    gap: var(--shelf-space-sm);
  }

  .card-footer-timestamp {
    font-size: var(--shelf-font-size-xs);
    color: var(--shelf-color-text-secondary);
    font-weight: var(--shelf-font-weight-normal);
  }

  .card-footer-action {
    margin-inline-start: auto;
    font-size: var(--shelf-font-size-sm);
    font-weight: var(--shelf-font-weight-semibold);
    color: var(--shelf-color-accent);
    background: none;
    border: none;
    padding: var(--shelf-space-xs) var(--shelf-space-sm);
    border-radius: var(--shelf-radius-sm);
    cursor: pointer;
    transition: opacity var(--shelf-duration-fast) var(--shelf-easing-default);
  }

  .card-footer-action:hover {
    opacity: 0.8;
  }

  .card-footer-action:focus-visible {
    outline: 2px solid var(--shelf-color-accent);
    outline-offset: 2px;
  }

  .card-footer-action:active {
    opacity: 0.6;
  }

  .card-footer-action:disabled {
    opacity: 0.4;
    cursor: not-allowed;
  }
}
